// Querying random replica nodes across different steps in the same user request
async fn get_timeline(client: &DbClient, user_id: u64) -> Vec<Post> {
    // First query goes to replica 1 (caught up)
    let p1 = client.read_replica_node(1, user_id).await.unwrap();

    // Second query goes to replica 2 (lagging behind)
    let p2 = client.read_replica_node(2, user_id).await.unwrap();
    // BUG: Timeline p2 might contain FEWER posts than p1, making time
    // appear to run backward for the client!
    p2
}
